import{_ as r,o as a,c as o,a0 as d}from"./chunks/framework.Czf8PZMA.js";const c=JSON.parse('{"title":"SECTION 06 16 00 — Wood Structural Sheathing（木结构覆面板·剪力/气密/防火）★可直接投用完整条款版★","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-section-wood-sheathing.md","filePath":"guide/09-section-wood-sheathing.md","lastUpdated":null}'),e={name:"guide/09-section-wood-sheathing.md"};function l(n,t,i,s,h,g){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="section-06-16-00-—-wood-structural-sheathing-木结构覆面板·剪力-气密-防火-★可直接投用完整条款版★" tabindex="-1">SECTION 06 16 00 — Wood Structural Sheathing（木结构覆面板·剪力/气密/防火）★可直接投用完整条款版★ <a class="header-anchor" href="#section-06-16-00-—-wood-structural-sheathing-木结构覆面板·剪力-气密-防火-★可直接投用完整条款版★" aria-label="Permalink to &quot;SECTION 06 16 00 — Wood Structural Sheathing（木结构覆面板·剪力/气密/防火）★可直接投用完整条款版★&quot;">​</a></h1><blockquote><p>📌 <strong>本文件是把 <code>04_木结构框架</code> 的「06 16 00」展开成可投用的 MasterFormat 三段式完整条款</strong>， 内嵌<strong>中美标准对应</strong>与<strong>合规流程停点</strong>。</p><ul><li>用法：复制进项目 SPEC，填 <code>[待定]</code> 处即可发出；Part 2/3 验收项可进采购/合同。</li><li>依据：<code>01_共享框架</code> §0.4 + <code>06_材料清单</code> §0.0 中美对应 + spec-agent 模板（WFCM/NDS）。</li><li>代码：MasterFormat 06 16 00 — Sheathing（覆面板）。</li></ul></blockquote><hr><h2 id="part-1-—-general-一般要求" tabindex="-1">PART 1 — GENERAL（一般要求） <a class="header-anchor" href="#part-1-—-general-一般要求" aria-label="Permalink to &quot;PART 1 — GENERAL（一般要求）&quot;">​</a></h2><h3 id="_1-1-章节范围" tabindex="-1">1.1 章节范围 <a class="header-anchor" href="#_1-1-章节范围" aria-label="Permalink to &quot;1.1 章节范围&quot;">​</a></h3><ul><li><strong>木结构模块之楼/屋面/剪力墙覆面板</strong>（OSB/胶合板 APA Exposure 1、石膏覆面板/专项防火板）：选型、铺设、固定（钉距）、<strong>模块间接缝处剪力连续性</strong>、运输损伤修复。</li><li>覆面板承载剪力墙横向力/侧向约束、气密性、防火分隔（火/烟路径）。</li><li>横向关联：06 05（结构木料/NAILS 固定）、06 17（工厂预制木桁架）、09 29（石膏板防火）、07 21（保温）、13 42（模块本体）、13 48（抗震）。</li></ul><h3 id="_1-2-引用文件" tabindex="-1">1.2 引用文件 <a class="header-anchor" href="#_1-2-引用文件" aria-label="Permalink to &quot;1.2 引用文件&quot;">​</a></h3><ul><li><strong>NDS</strong>（木结构设计）/ <strong>WFCM</strong>（木框架构造手册，剪力墙/侧向）</li><li><strong>APA Exposure 1</strong>（胶合板/OSB 等级、湿度等级）</li><li><strong>APA PRG-320</strong>（如需 CLT）、<strong>ASTM C1396</strong>（石膏覆面板）、<strong>TPI 1</strong>（桁架，如集成）</li><li><strong>AWPA</strong>（防腐木，接触地/砼）</li><li>加州/联邦：<strong>CBC（Title 24 Part 2，IBC Ch.23 + 州修正）</strong>、<strong>Type IIIA/V 层高限制</strong>（CBC）、<strong>CFC（Part 9）</strong> 防火、<strong>HCD Title 25 §3032</strong>（检率）、<strong>HSC §19980</strong>（insignia）</li><li>中美对应：<strong>GB 50005 / GB/T 50708</strong>（木结构）、<strong>GB/T 9846</strong>（胶合板）、<strong>GB/T 20241</strong>（OSB）、<strong>GB/T 26899</strong>（CLT）、<strong>GB/T 22102</strong>（防腐木）——详见 2.1。</li></ul><h3 id="_1-3-提交要求" tabindex="-1">1.3 提交要求 <a class="header-anchor" href="#_1-3-提交要求" aria-label="Permalink to &quot;1.3 提交要求&quot;">​</a></h3><ul><li>覆面板选型表（类型/等级/厚度/钉型/钉距）+ 委派设计剪力计算（加州执照 SE 复核）。</li><li>湿度/含水率含水报告（MC% ≤19%；外观件 6-12%）；防潮垫层/运输保护声明。</li><li>运输损伤（受潮/开裂/脱层）修复方案 + NCR 记录。</li><li>FAT 清单 + ITP。</li></ul><h3 id="_1-4-质量保证" tabindex="-1">1.4 质量保证 <a class="header-anchor" href="#_1-4-质量保证" aria-label="Permalink to &quot;1.4 质量保证&quot;">​</a></h3><ul><li>覆面板粘贴/固定按 WFCM 钉距表；现场剪力补强板安装；工厂 QAA + Title 25 §3032 检率（新型号100%→首10台→25%）。</li></ul><h3 id="_1-5-交货存储" tabindex="-1">1.5 交货存储 <a class="header-anchor" href="#_1-5-交货存储" aria-label="Permalink to &quot;1.5 交货存储&quot;">​</a></h3><ul><li>运输防潮/防变形加固；现场防雨覆盖（Exposure 1 不代表耐泡水）；到货含水率抽检。</li></ul><hr><h2 id="part-2-—-products-产品-材料" tabindex="-1">PART 2 — PRODUCTS（产品/材料） <a class="header-anchor" href="#part-2-—-products-产品-材料" aria-label="Permalink to &quot;PART 2 — PRODUCTS（产品/材料）&quot;">​</a></h2><h3 id="_2-1-中美材料换算表-写入采购-★" tabindex="-1">2.1 中美材料换算表（写入采购）★ <a class="header-anchor" href="#_2-1-中美材料换算表-写入采购-★" aria-label="Permalink to &quot;2.1 中美材料换算表（写入采购）★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部位</th><th>美国标准（验收基准）</th><th>中国对应规范</th><th>差异处理</th></tr></thead><tbody><tr><td>覆面板（OSB/胶合板）</td><td><strong>APA Exposure 1</strong>（湿度等级）+ 厚度/等级</td><td><strong>GB/T 9846</strong>（胶合板）、<strong>GB/T 20241</strong>（OSB）</td><td>甲醛释放/强度/防潮等级对标；AF 等级互认</td></tr><tr><td>石膏覆面板/防火板</td><td><strong>ASTM C1396</strong></td><td>GB/T 9775（纸面石膏板）、GB 8624-2008</td><td>燃烧分级/厚度对标 09 29</td></tr><tr><td>木结构设计</td><td>NDS / WFCM / CBC Ch.23</td><td><strong>GB 50005</strong></td><td>加州以 CBC 验收；中标内部参考</td></tr><tr><td>胶合木/CLT（重木）</td><td><strong>APA PRG-320</strong></td><td><strong>GB/T 26899</strong></td><td>层板等级/炭化计算对标 06 13</td></tr><tr><td>防腐木</td><td><strong>AWPA</strong></td><td><strong>GB/T 22102</strong></td><td>防腐等级互认</td></tr><tr><td>固定件（钉）</td><td>按 WFCM 钉距/钉型</td><td>GB/T 116(钉)、对标</td><td>钉径/长度按 WFCM</td></tr></tbody></table><h3 id="_2-2-材料构件" tabindex="-1">2.2 材料构件 <a class="header-anchor" href="#_2-2-材料构件" aria-label="Permalink to &quot;2.2 材料构件&quot;">​</a></h3><ul><li>覆面板：OSB/胶合板 <strong>APA Exposure 1</strong>、等级与厚度按剪力墙/楼屋面设计 [待定 mm]；石膏覆面板按 ASTM C1396（防火时）。</li><li>固定件：环纹钉/常见钉依 WFCM 钉距表；模块间补强覆面板/短板。</li><li>防潮垫层/防潮膜与运输保护件。</li></ul><hr><h2 id="part-3-—-execution-安装与执行" tabindex="-1">PART 3 — EXECUTION（安装与执行） <a class="header-anchor" href="#part-3-—-execution-安装与执行" aria-label="Permalink to &quot;PART 3 — EXECUTION（安装与执行）&quot;">​</a></h2><h3 id="_3-1-工厂铺设-fc-段" tabindex="-1">3.1 工厂铺设（FC 段） <a class="header-anchor" href="#_3-1-工厂铺设-fc-段" aria-label="Permalink to &quot;3.1 工厂铺设（FC 段）&quot;">​</a></h3><ul><li>覆面板铺设顺序 + 钉顺序（横撑/边柱）；模块间接缝处<strong>交错错缝 + 额外钉距 + 封边连接</strong>。</li><li>模块间剪力连续性设计（剪力墙在接缝连续）→ 覆盖面板在现场接缝补齐。</li><li>含水率 QC（MC% 记录）；防潮垫层。</li></ul><h3 id="_3-2-现场剪力补强-现场段" tabindex="-1">3.2 现场剪力补强（现场段） <a class="header-anchor" href="#_3-2-现场剪力补强-现场段" aria-label="Permalink to &quot;3.2 现场剪力补强（现场段）&quot;">​</a></h3><ul><li>现场接缝覆面板/短板安装；剪力墙连续性补齐（对齐 CBC Ch.23 / WFCM）。</li><li>运输损伤修复（受潮/开裂/脱层判定）：剪切板缺钉返点、脱层返厂/更换，NCR 关闭。</li></ul><h3 id="_3-3-模块间接缝与防火" tabindex="-1">3.3 模块间接缝与防火 <a class="header-anchor" href="#_3-3-模块间接缝与防火" aria-label="Permalink to &quot;3.3 模块间接缝与防火&quot;">​</a></h3><ul><li>模块间接缝处覆面连续性 + 防火分隔（火/烟路径阻断）→ 07 84 防火封堵 → 石膏板 09 29 封闭。</li><li>气密性（07 27）随覆面试验收；隐蔽前 hold point。</li></ul><h3 id="_3-4-检验与停点-hold-points-★★★★" tabindex="-1">3.4 检验与停点（Hold Points）★★★★ <a class="header-anchor" href="#_3-4-检验与停点-hold-points-★★★★" aria-label="Permalink to &quot;3.4 检验与停点（Hold Points）★★★★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>停点</th><th>时机</th><th>验收项</th><th>放行</th></tr></thead><tbody><tr><td><strong>HP-1</strong></td><td>出厂前</td><td>覆面等级/厚度/钉距/含水率 MSP + FAT</td><td>工厂 QAA 签 + insignia</td></tr><tr><td><strong>HP-2</strong></td><td>现场就位前</td><td>覆面板受潮/损坏抽检、运输加固</td><td>现场验收单</td></tr><tr><td><strong>HP-3</strong></td><td>隐蔽前</td><td>剪力连续性、钉距抽检、火/烟封堵、气密</td><td>NCR 关闭 + 三重放行</td></tr></tbody></table><hr><h2 id="验收汇总表-可进合同" tabindex="-1">验收汇总表（可进合同） <a class="header-anchor" href="#验收汇总表-可进合同" aria-label="Permalink to &quot;验收汇总表（可进合同）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>性能/验收要求</th><th>标准</th></tr></thead><tbody><tr><td>覆面板等级</td><td>APA Exposure 1</td><td>APA</td></tr><tr><td>含水率</td><td>≤19%（外观 6-12%）</td><td>NDS/WFCM</td></tr><tr><td>钉距/钉型</td><td>按 WFCM 剪力墙钉距表</td><td>WFCM</td></tr><tr><td>剪力连续性</td><td>模块接缝连续、现场补齐</td><td>CBC Ch.23 / WFCM</td></tr><tr><td>检验频率</td><td>新型号100%→首10台→25%（可降）</td><td>HCD Title 25 §3032</td></tr><tr><td>出厂放行</td><td>insignia + 三重放行</td><td>HSC §19980 + 01 45</td></tr></tbody></table><hr><p><em>本完整 SECTION 由 Modular-Agent 依据 WFCM/NDS + spec-agent 模板 + <code>01_共享框架</code> §0.4 编制；Part 2 中美对应内嵌中国工厂对标需求（GB/T 9846 OSB/胶合板、GB/T 26899 CLT）。入口与流程见 <code>00_操作手册总纲</code>。</em></p>',35)])])}const C=r(e,[["render",l]]);export{c as __pageData,C as default};
